"""JSON-file-backed implementation of :class:`~auditlog.service.AuditLogService`.

Two on-disk formats are understood: the current append-only format
(``store_version`` 2), which this class can also write to, and the legacy
archive format (``store_version`` 1), which is read-only history handled by
:mod:`auditlog.archive`. Writes are append-only: the whole file is rewritten
to a temporary path and atomically swapped in, but no existing entry is ever
edited or removed.
"""

from __future__ import annotations

import json
import os
import tempfile
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

from . import archive
from .models import AuditEvent, content_digest
from .service import AuditLogService, IntegrityError, RepairReport, UnsupportedOperationError

CURRENT_STORE_VERSION = 2


def _now_iso() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def _entry_to_dict(event: AuditEvent) -> dict[str, Any]:
    return {
        "event_id": event.event_id,
        "sequence": event.sequence,
        "actor": event.actor,
        "action": event.action,
        "outcome": event.outcome,
        "recorded_at": event.recorded_at,
        "metadata": event.metadata,
    }


def _find_integrity_issues(events: list[AuditEvent]) -> tuple[tuple[int, ...], int | None]:
    corrupted = tuple(event.sequence for event in events if event.event_id != event.recomputed_id())
    gap_at = None
    for index, event in enumerate(events, start=1):
        if event.sequence != index:
            gap_at = index
            break
    return corrupted, gap_at


class JsonFileLogStore(AuditLogService):
    """The append-only trail rooted at a single JSON ``--log-store`` file."""

    def __init__(self, path: str | Path) -> None:
        self._path = Path(path)

    @property
    def index_path(self) -> Path:
        return self._path.with_suffix(self._path.suffix + ".index.json")

    def _read_raw(self) -> dict[str, Any]:
        if not self._path.exists():
            return {"store_version": CURRENT_STORE_VERSION, "entries": []}
        with self._path.open("r", encoding="utf-8") as handle:
            return json.load(handle)

    def _load_events(self) -> tuple[int, list[AuditEvent]]:
        raw = self._read_raw()
        version = raw.get("store_version", CURRENT_STORE_VERSION)
        if version == 1:
            return version, archive.load_legacy_entries(raw)
        if version == CURRENT_STORE_VERSION:
            events = [
                AuditEvent(
                    event_id=entry["event_id"],
                    sequence=entry["sequence"],
                    actor=entry["actor"],
                    action=entry["action"],
                    outcome=entry["outcome"],
                    recorded_at=entry["recorded_at"],
                    source_version=version,
                    metadata=entry.get("metadata", {}),
                )
                for entry in raw.get("entries", [])
            ]
            return version, events
        raise UnsupportedOperationError(f"unsupported store_version {version!r}")

    def _verified_events(self) -> list[AuditEvent]:
        _, events = self._load_events()
        corrupted, gap_at = _find_integrity_issues(events)
        if corrupted or gap_at is not None:
            raise IntegrityError(
                f"trail integrity check failed: corrupted sequences={list(corrupted)}, "
                f"gap at sequence={gap_at}; run 'repair' for a full report"
            )
        return events

    def _write_events(self, events: list[AuditEvent]) -> None:
        payload = {
            "store_version": CURRENT_STORE_VERSION,
            "entries": [_entry_to_dict(event) for event in events],
        }
        self._path.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp_name = tempfile.mkstemp(
            dir=str(self._path.parent) or ".", prefix=self._path.name + ".", suffix=".tmp"
        )
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                json.dump(payload, handle, indent=2, sort_keys=True)
                handle.write("\n")
            os.replace(tmp_name, self._path)
        except BaseException:
            os.unlink(tmp_name)
            raise

    def record(
        self,
        actor: str,
        action: str,
        outcome: str,
        *,
        metadata: dict[str, Any] | None = None,
        recorded_at: str | None = None,
    ) -> AuditEvent:
        version, events = self._load_events()
        if version != CURRENT_STORE_VERSION:
            raise UnsupportedOperationError(
                f"cannot append to a store_version {version} archive; it is read-only history"
            )
        corrupted, gap_at = _find_integrity_issues(events)
        if corrupted or gap_at is not None:
            raise IntegrityError(
                f"refusing to append onto a corrupted trail: corrupted sequences={list(corrupted)}, "
                f"gap at sequence={gap_at}; run 'repair' for a full report"
            )

        recorded_at = recorded_at or _now_iso()
        next_sequence = events[-1].sequence + 1 if events else 1
        event_id = content_digest(actor, action, outcome, recorded_at)
        new_event = AuditEvent(
            event_id=event_id,
            sequence=next_sequence,
            actor=actor,
            action=action,
            outcome=outcome,
            recorded_at=recorded_at,
            source_version=CURRENT_STORE_VERSION,
            metadata=dict(metadata or {}),
        )
        self._write_events(events + [new_event])
        return new_event

    def query(self, *, actor: str | None = None, action: str | None = None) -> list[AuditEvent]:
        events = self._verified_events()
        if actor is not None:
            events = [event for event in events if event.actor == actor]
        if action is not None:
            events = [event for event in events if event.action == action]
        return events

    def repair(self) -> RepairReport:
        _, events = self._load_events()
        corrupted, gap_at = _find_integrity_issues(events)

        by_actor: dict[str, list[str]] = {}
        by_action: dict[str, list[str]] = {}
        for event in events:
            by_actor.setdefault(event.actor, []).append(event.event_id)
            by_action.setdefault(event.action, []).append(event.event_id)
        index_payload = {
            "generated_from_count": len(events),
            "by_actor": by_actor,
            "by_action": by_action,
        }
        self.index_path.parent.mkdir(parents=True, exist_ok=True)
        with self.index_path.open("w", encoding="utf-8") as handle:
            json.dump(index_payload, handle, indent=2, sort_keys=True)
            handle.write("\n")

        return RepairReport(
            verified_count=len(events),
            corrupted_sequences=corrupted,
            sequence_gap_at=gap_at,
            rebuilt_index_path=str(self.index_path),
        )

"""Strict domain models for the audit log.

An entry's identity is the recorded content itself: ``actor``, ``action``,
``outcome`` and ``recorded_at`` are hashed together to produce ``event_id``.
Everything else here exists to keep malformed content out of the trail before
it is ever hashed: an unparsable actor, an outcome outside the fixed set, an
id that isn't a real content digest, or a sequence that isn't a positive
integer are all rejected at construction time rather than discovered later.
"""

from __future__ import annotations

import enum
import hashlib
import re
from dataclasses import dataclass, field
from typing import Any

# The fields that constitute an entry's identity. Anything outside this tuple
# is descriptive: it may differ between two records of the same event without
# making them different events.
IDENTIFYING_FIELDS: tuple[str, ...] = ("actor", "action", "outcome", "recorded_at")

EVENT_ID_LENGTH = 64
_EVENT_ID_RE = re.compile(r"^[0-9a-f]{%d}$" % EVENT_ID_LENGTH)

# kind:name, e.g. "operator:mina" or "service:indexer". The kind is the
# actor's category (lowercase, snake_case); the name identifies the specific
# actor within it.
_IDENTITY_RE = re.compile(r"^(?P<kind>[a-z][a-z0-9_]*):(?P<name>[A-Za-z0-9][A-Za-z0-9._-]*)$")


class AuditModelError(ValueError):
    """Base class for content that cannot become part of the trail."""


class InvalidActorError(AuditModelError):
    """Raised when an actor string does not parse as ``kind:name``."""


class InvalidOutcomeError(AuditModelError):
    """Raised when an outcome is outside the fixed {allowed, denied} set."""


class InvalidEventIdError(AuditModelError):
    """Raised when an id is not a well-formed content digest."""


class InvalidSequenceError(AuditModelError):
    """Raised when a sequence number is not a positive integer."""


class Outcome(str, enum.Enum):
    """The fixed, closed set of outcomes an audited action can have."""

    ALLOWED = "allowed"
    DENIED = "denied"

    @classmethod
    def coerce(cls, value: str) -> "Outcome":
        """Validate ``value`` against the fixed set; never widen it silently."""

        try:
            return cls(value)
        except ValueError:
            known = ", ".join(member.value for member in cls)
            raise InvalidOutcomeError(
                f"unknown outcome {value!r}; expected one of: {known}"
            ) from None


@dataclass(frozen=True)
class Identity:
    """An actor's parsed ``kind:name`` identity.

    ``kind`` groups actors that share the same access policy (for example
    ``operator`` or ``service``); ``name`` identifies one actor within it.
    """

    kind: str
    name: str

    @classmethod
    def parse(cls, actor: str) -> "Identity":
        match = _IDENTITY_RE.match(actor)
        if match is None:
            raise InvalidActorError(
                f"malformed actor {actor!r}; expected 'kind:name' (lowercase kind, non-empty name)"
            )
        return cls(kind=match.group("kind"), name=match.group("name"))

    def __str__(self) -> str:
        return f"{self.kind}:{self.name}"


def is_valid_event_id(value: str) -> bool:
    """Whether ``value`` has the shape of a content digest, independent of content."""

    return isinstance(value, str) and bool(_EVENT_ID_RE.match(value))


def content_digest(actor: str, action: str, outcome: str, recorded_at: str) -> str:
    """Return the deterministic event id for this entry's recorded content.

    Identity is the recorded content itself, so the same event recorded twice
    collapses to one id and any later edit to a stored entry is detectable by
    recomputing this. The separator cannot appear in a field value, so distinct
    inputs cannot collide by concatenation.
    """

    joined = "\x1f".join((actor, action, outcome, recorded_at))
    return hashlib.sha256(joined.encode("utf-8")).hexdigest()


@dataclass(frozen=True)
class AuditEvent:
    """One recorded entry in the append-only trail.

    ``sequence`` is the entry's gapless position in the trail and ``event_id``
    is its content digest. ``source_version`` records which store format the
    entry was read from, and ``metadata`` carries caller-supplied context such
    as an archive's own reference. Both are descriptive: they explain an entry,
    and are never an input to its identity or to whether it is retained.

    Construction validates the entry's content in isolation (actor shape,
    outcome membership, id shape, sequence positivity). It does not, and
    cannot, check trail-wide invariants like gaplessness across entries or
    whether ``event_id`` actually matches this content -- that is
    ``recomputed_id`` and the store's integrity check.
    """

    event_id: str
    sequence: int
    actor: str
    action: str
    outcome: str
    recorded_at: str
    source_version: int = 2
    metadata: dict[str, Any] = field(default_factory=dict)

    def __post_init__(self) -> None:
        Identity.parse(self.actor)
        Outcome.coerce(self.outcome)
        if not is_valid_event_id(self.event_id):
            raise InvalidEventIdError(
                f"invalid event id {self.event_id!r}; expected {EVENT_ID_LENGTH} lowercase hex characters"
            )
        if isinstance(self.sequence, bool) or not isinstance(self.sequence, int) or self.sequence < 1:
            raise InvalidSequenceError(
                f"invalid sequence {self.sequence!r}; expected a positive integer"
            )
        if not self.action:
            raise AuditModelError("action must be a non-empty string")
        if not self.recorded_at:
            raise AuditModelError("recorded_at must be a non-empty timestamp string")

    @property
    def identity(self) -> Identity:
        return Identity.parse(self.actor)

    def recomputed_id(self) -> str:
        """The id this entry's current content implies; compare to ``event_id``."""

        return content_digest(self.actor, self.action, self.outcome, self.recorded_at)

"""Request-path helpers shared by authentication and dispatch.

Versioned routes and proxy spellings should pass through one helper so a
documented path and a harmless alternate spelling reach the same decision.
"""
from __future__ import annotations

from urllib.parse import unquote


def canonical_path(raw_path: str) -> str:
    """Compatibility spelling: decode, collapse slashes, drop one trailing slash."""

    path = unquote(raw_path)
    while "//" in path:
        path = path.replace("//", "/")
    if len(path) > 1:
        path = path.rstrip("/")
    return path or "/"


def auth_path(raw_path: str) -> str:
    """Path used to look up the route before reading a body."""

    # Decode the request spelling before the route-table lookup.
    return unquote(raw_path)


def dispatch_path(raw_path: str) -> str:
    """Path handed to the handler after the route decision."""

    # Hand the handler the same path the route lookup used.
    return auth_path(raw_path)

"""Route and access-policy models for the HTTP-facing side of the service.

A ``Route`` maps an HTTP method and canonical path to the audit ``action`` it
represents. An ``AccessPolicyTable`` then decides, for a caller ``Identity``
and that action, whether the call is ``allowed`` or ``denied``. Both models
are strict: a route with a non-canonical path, or a request for an unknown
route, is a configuration error rather than something to guess at silently.

This keeps request-path matching in :mod:`auditlog.paths` as the single
helper both authentication and dispatch share, and turns its output into the
``actor``/``action``/``outcome`` triple the audit log records.
"""

from __future__ import annotations

from dataclasses import dataclass

from .models import Identity, Outcome
from .paths import canonical_path

_ALLOWED_METHODS = frozenset({"GET", "POST", "PUT", "PATCH", "DELETE"})


class PolicyModelError(ValueError):
    """Base class for malformed route or access-policy configuration."""


class InvalidRouteError(PolicyModelError):
    """Raised when a route's method or path is not well-formed."""


@dataclass(frozen=True)
class Route:
    """One HTTP endpoint and the audit action it corresponds to."""

    method: str
    path: str
    action: str

    def __post_init__(self) -> None:
        method = self.method.upper()
        if method not in _ALLOWED_METHODS:
            allowed = ", ".join(sorted(_ALLOWED_METHODS))
            raise InvalidRouteError(f"unsupported method {self.method!r}; expected one of: {allowed}")
        object.__setattr__(self, "method", method)
        if not self.path.startswith("/"):
            raise InvalidRouteError(f"route path {self.path!r} must start with '/'")
        if self.path != canonical_path(self.path):
            raise InvalidRouteError(
                f"route path {self.path!r} is not canonical; use {canonical_path(self.path)!r}"
            )
        if not self.action:
            raise InvalidRouteError("route action must be a non-empty string")


class RouteTable:
    """Looks up the :class:`Route` for a method and raw request path."""

    def __init__(self, routes: list[Route]) -> None:
        self._routes: dict[tuple[str, str], Route] = {}
        for route in routes:
            key = (route.method, route.path)
            if key in self._routes:
                raise InvalidRouteError(f"duplicate route for {route.method} {route.path}")
            self._routes[key] = route

    def match(self, method: str, raw_path: str) -> Route | None:
        return self._routes.get((method.upper(), canonical_path(raw_path)))


@dataclass(frozen=True)
class AccessPolicy:
    """The set of actions one identity kind is permitted to perform."""

    identity_kind: str
    allowed_actions: frozenset[str]

    def permits(self, action: str) -> bool:
        return action in self.allowed_actions


class AccessPolicyTable:
    """Decides the outcome of an identity attempting an action."""

    def __init__(self, policies: list[AccessPolicy]) -> None:
        self._policies: dict[str, AccessPolicy] = {}
        for policy in policies:
            if policy.identity_kind in self._policies:
                raise PolicyModelError(f"duplicate access policy for kind {policy.identity_kind!r}")
            self._policies[policy.identity_kind] = policy

    def decide(self, identity: Identity, action: str) -> Outcome:
        policy = self._policies.get(identity.kind)
        if policy is None or not policy.permits(action):
            return Outcome.DENIED
        return Outcome.ALLOWED

    @property
    def is_clean(self) -> bool:
        return (
            not self.corrupted_sequences
            and self.sequence_gap_at is None
            and not self.reordered_sequences
            and self.count_mismatch is None
        )


@dataclass(frozen=True)
class ImportReport:
    """The result of one ``import_events`` call (fresh, replayed, or resumed)."""

    idempotency_key: str
    status: str
    requested_count: int
    applied_count: int
    duplicate_count: int


class AuditLogService(ABC):
    """Record, query and verify an append-only compliance audit trail."""

    @abstractmethod
    def record(
        self,
        actor: str,
        action: str,
        outcome: str,

